T={(3,7),(4,6),(4,8),(5,5),(5,6),(5,8)}
objs={2:[(3,13),(4,12),(5,11)], 8:[(1,23),(2,22),(3,22)],5:[(9,25),(10,24),(10,25)],6:[(11,5),(12,5),(12,7)],3:[(11,15),(12,16),(13,16)],7:[(19,11),(20,12)],9:[(22,5),(23,3)]}
for color,pts in objs.items():
    # placement origin = source coord - template coord
    origins=set((r-tr,c-tc) for r,c in pts for tr,tc in T)
    valid=[o for o in origins if all((r-o[0],c-o[1]) in T for r,c in pts)]
    print(color,pts,valid, 'positions', [[(o[0]+r,o[1]+c) for r,c in sorted(T)] for o in valid])

H=W=30
g=[[1]*W for _ in range(H)]
# actual template object at absolute coords
for r,c in T:g[r][c]=4
placements={2:[(0,6),(16,16)],8:[(-2,16)],5:[(5,19)],6:[(7,-1)],3:[(8,8)],7:[(16,4)],9:[(18,-3)]}
for color,origins in placements.items():
    for ro,co in origins:
        for tr,tc in T:
            r,c=ro+tr,co+tc
            assert 0<=r<H and 0<=c<W, (color,r,c)
            assert g[r][c]==1 or g[r][c]==color, (color,r,c,g[r][c])
            g[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in g))
